#!/usr/bin/env python3
import hashlib,json,subprocess,sys
from pathlib import Path
D=Path(__file__).resolve().parents[2];P=D/'research/nine-sharing-sign25-expression-equivalence-check';R=D.parents[1];H=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
pins={'run.py':'83cef530879d27e5f1b95bcb0dd87a9e16b3084a66743602602846308f960ee7','source-manifest.json':'6c0126f7ac2314c08da0c2648abd356b841b3c78996fedce55f5767b1bf0f0d2','evaluator-union-survey.py':'eaaf227d8c8021acf5cb47328e7077a62c2bf86ee84102b4dc3313c41838965c','union.json':'cce11fb00742606981e9dfe8ba03bf692ac73ec798d250438cb09185548f5623','src/DiophantineConsistency/Sign25ExpressionEquivalence.lean':'c086e008252df8e384d4ce9641d049f5c921a37e704b313ea9ffd55571f81dca'}
for p,h in pins.items():assert H(P/p)==h
m=json.loads((P/'source-manifest.json').read_text());assert len(m['rows'])==1;e=m['rows'][0];assert e['module']=='DiophantineConsistency.Sign25ExpressionEquivalence' and e['imports']==['DiophantineConsistency.Sign25CurrentExpressionEval','DiophantineConsistency.Sign26CurrentExpressionEval','DiophantineConsistency.Sign25SeedExistential'] and e['source_sha256']==pins['src/DiophantineConsistency/Sign25ExpressionEquivalence.lean'] and H(R/e['source'])==e['source_sha256']
s=(P/'src/DiophantineConsistency/Sign25ExpressionEquivalence.lean').read_text();assert all(x in s for x in ['Fin.cons (1 : V) w','Fin.tail v','Fin.cons_self_tail v','∃ w : Fin 25 → V','∃ w : Fin 26 → V','Sign25CurrentExpression.eval_expression','Sign26CurrentExpression.eval_expression','Sign25SeedIff.exists_same_input CurrentWindowCarry2011.ports (1 : V)','c26.symm.trans h26.symm'])
for n,h in [('nine-sharing-sign25-seed-iff-terminal-frontier-independent','cf70b18afea58dacc013b8bfa3a3b6e4aca1e58da78abc53d1dc5a11447eecca'),('nine-sharing-sign25-expression-eval-terminal-frontier-independent','adb2983992b6c7c3ef4c0991c6292336f2ec3ad4288ae9a9a8dee30bcf48c7f1'),('nine-sharing-sign26-expression-eval-terminal-frontier-independent','cfb5f67ddef456f6e82061ee17a4dd1b17d90ee2f8147207fe465085d46ef0b4')]:
 q=D/'reviews'/n/'check.py';assert H(q)==h;subprocess.run([sys.executable,'-I','-S','-B',str(q)],check=True,capture_output=True,timeout=120)
r=subprocess.run([sys.executable,'-I','-S','-B',str(P/'evaluator-union-survey.py')],check=True,capture_output=True,text=True,timeout=120);u=json.loads(r.stdout);assert u['status']=='PASS' and all(u['evaluators'][n]['overlap_count']==1059 and u['evaluators'][n]['extra_count']==1 for n in ('25','26'))
r=subprocess.run([sys.executable,'-I','-S','-B',str(P/'run.py'),'--preflight'],check=True,capture_output=True,text=True,timeout=120);assert json.loads(r.stdout)['status']=='PASS_NO_LEAN_PREFLIGHT'
